  "gauge-chart": {"usage":{"lang":"vue","code":"<GaugeChart label=\"Describe the chart\" aria-describedby=\"chart-data\">\n  <svg viewBox=\"0 0 10 10\">...</svg>\n</GaugeChart>\n"},"variants":[{"title":"Graphic only (no data table)","html":"<figure class=\"gauge-chart\"><div class=\"gauge-chart-graphic\" role=\"img\" aria-label=\"Speed gauge: 72 out of 100\"><svg viewBox=\"0 0 120 80\" width=\"240\" height=\"160\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M10 70 A50 50 0 0 1 110 70\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\"0.25\" stroke-width=\"10\"/><path d=\"M10 70 A50 50 0 0 1 90 33\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"10\"/></svg></div></figure>"}]},
  "heatmap-chart": {"usage":{"lang":"vue","code":"<HeatmapChart label=\"Describe the chart\" aria-describedby=\"chart-data\">\n  <svg viewBox=\"0 0 10 10\">...</svg>\n</HeatmapChart>\n"},"variants":[{"title":"Graphic only (no data table)","html":"<figure class=\"heatmap-chart\"><div class=\"heatmap-chart-graphic\" role=\"img\" aria-label=\"Activity heatmap by day and period\"><svg viewBox=\"0 0 120 80\" width=\"240\" height=\"160\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"10\" y=\"10\" width=\"30\" height=\"30\" fill=\"currentColor\" fill-opacity=\"0.2\"/><rect x=\"45\" y=\"10\" width=\"30\" height=\"30\" fill=\"currentColor\" fill-opacity=\"0.5\"/><rect x=\"80\" y=\"10\" width=\"30\" height=\"30\" fill=\"currentColor\" fill-opacity=\"0.9\"/><rect x=\"10\" y=\"45\" width=\"30\" height=\"30\" fill=\"currentColor\" fill-opacity=\"0.6\"/><rect x=\"45\" y=\"45\" width=\"30\" height=\"30\" fill=\"currentColor\" fill-opacity=\"0.3\"/><rect x=\"80\" y=\"45\" width=\"30\" height=\"30\" fill=\"currentColor\" fill-opacity=\"0.7\"/></svg></div></figure>"}]},
  "radar-chart": {"usage":{"lang":"vue","code":"<RadarChart label=\"Describe the chart\" aria-describedby=\"chart-data\">\n  <svg viewBox=\"0 0 10 10\">...</svg>\n</RadarChart>\n"},"variants":[{"title":"Graphic only (no data table)","html":"<figure class=\"radar-chart\"><div class=\"radar-chart-graphic\" role=\"img\" aria-label=\"Skills radar across five axes\"><svg viewBox=\"0 0 120 80\" width=\"240\" height=\"160\" aria-hidden=\"true\" focusable=\"false\"><polygon points=\"60,10 105,40 88,70 32,70 15,40\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\"0.25\"/><polygon points=\"60,22 92,42 78,62 40,60 28,42\" fill=\"currentColor\" fill-opacity=\"0.3\" stroke=\"currentColor\"/></svg></div></figure>"}]},
  "sankey-chart": {"usage":{"lang":"vue","code":"<SankeyChart label=\"Describe the chart\" aria-describedby=\"chart-data\">\n  <svg viewBox=\"0 0 10 10\">...</svg>\n</SankeyChart>\n"},"variants":[{"title":"Graphic only (no data table)","html":"<figure class=\"sankey-chart\"><div class=\"sankey-chart-graphic\" role=\"img\" aria-label=\"Flow from sources to outcomes\"><svg viewBox=\"0 0 120 80\" width=\"240\" height=\"160\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"5\" y=\"10\" width=\"8\" height=\"60\" fill=\"currentColor\"/><rect x=\"107\" y=\"10\" width=\"8\" height=\"25\" fill=\"currentColor\"/><rect x=\"107\" y=\"45\" width=\"8\" height=\"25\" fill=\"currentColor\"/><path d=\"M13 14 C60 14 60 14 107 14 L107 34 C60 34 60 34 13 34 Z\" fill=\"currentColor\" fill-opacity=\"0.3\"/><path d=\"M13 44 C60 44 60 49 107 49 L107 69 C60 69 60 64 13 64 Z\" fill=\"currentColor\" fill-opacity=\"0.3\"/></svg></div></figure>"}]},
