  "pie-chart": {"usage":{"lang":"vue","code":"<PieChart label=\"Describe the chart\" aria-describedby=\"chart-data\">\n  <svg viewBox=\"0 0 10 10\">...</svg>\n</PieChart>\n"},"variants":[{"title":"Graphic only (no data table)","html":"<figure class=\"pie-chart\"><div class=\"pie-chart-graphic\" role=\"img\" aria-label=\"Pie chart: share of three products\"><svg viewBox=\"0 0 120 80\" width=\"240\" height=\"160\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"60\" cy=\"40\" r=\"30\" fill=\"currentColor\" fill-opacity=\"0.25\"/><path d=\"M60 40 L60 10 A30 30 0 0 1 90 40 Z\" fill=\"currentColor\"/><path d=\"M60 40 L90 40 A30 30 0 0 1 45 66 Z\" fill=\"currentColor\" fill-opacity=\"0.6\"/></svg></div></figure>"}]},
  "ring-chart": {"usage":{"lang":"vue","code":"<RingChart label=\"Describe the chart\" aria-describedby=\"chart-data\">\n  <svg viewBox=\"0 0 10 10\">...</svg>\n</RingChart>\n"},"variants":[{"title":"Graphic only (no data table)","html":"<figure class=\"ring-chart\"><div class=\"ring-chart-graphic\" role=\"img\" aria-label=\"Ring chart: 72 percent of target\"><svg viewBox=\"0 0 120 80\" width=\"240\" height=\"160\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"60\" cy=\"40\" r=\"28\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\"0.25\" stroke-width=\"10\"/><path d=\"M60 12 A28 28 0 1 1 33 49\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"10\"/></svg></div></figure>"}]},
